      {
        error: "Periksa isian yang ditandai.",
        fields: Object.fromEntries(
          error.issues.map((i) => [i.path.at(-1), i.message]),
        ),
      },
      { status: 422 },
    );
  if (error instanceof HttpError)
    return NextResponse.json(
      { error: error.message },
      { status: error.status },
    );
